        private void ConfigureSidebarButton(Button button, string text, bool selected)
        {
            button.BackColor = selected ? Color.DodgerBlue : Color.FromArgb(0, 82, 204);
            button.Dock = DockStyle.Top;
            button.FlatAppearance.BorderSize = 0;
            button.FlatAppearance.MouseOverBackColor = Color.FromArgb(30, 144, 255);
            button.FlatStyle = FlatStyle.Flat;
            button.Font = new Font("Segoe UI", 9F, FontStyle.Bold, GraphicsUnit.Point, 0);
            button.ForeColor = Color.White;
            button.Location = new Point(0, 0);
            button.Name = button.Name;
            button.Padding = new Padding(16, 0, 0, 0);
            button.Size = new Size(220, 52);
            button.TabIndex = 0;
            button.Text = text;
            button.TextAlign = ContentAlignment.MiddleLeft;
            button.UseVisualStyleBackColor = false;
        }

        private void ConfigureContentPanel(Panel panel, bool visible)
        {
            panel.AutoScroll = true;
            panel.BackColor = Color.White;
            panel.Dock = DockStyle.Fill;
            panel.Location = new Point(0, 0);
            panel.Name = panel.Name;
            panel.Padding = new Padding(0, 0, 0, 24);
            panel.Size = new Size(700, 500);
            panel.TabIndex = 0;
            panel.Visible = visible;
        }

        private void ConfigureSectionTitle(Label label, string text, int x, int y)
        {
            label.AutoSize = true;
            label.Font = new Font("Segoe UI", 12F, FontStyle.Bold, GraphicsUnit.Point, 0);
            label.ForeColor = Color.FromArgb(0, 82, 204);
            label.Location = new Point(x, y);
            label.Name = label.Name;
            label.Size = new Size(100, 28);
            label.TabIndex = 0;
            label.Text = text;
        }

        private void ConfigureFieldLabel(Label label, string text, int x, int y)
        {
            label.AutoSize = true;
            label.Font = new Font("Segoe UI", 9F, FontStyle.Bold, GraphicsUnit.Point, 0);
            label.ForeColor = Color.FromArgb(20, 52, 110);
            label.Location = new Point(x, y);
            label.Name = label.Name;
            label.Size = new Size(100, 25);
            label.TabIndex = 0;
            label.Text = text;
        }

        private void ConfigureHint(Label label, string text, int x, int y)
        {
            label.AutoSize = true;
            label.Font = new Font("Segoe UI", 9F, FontStyle.Regular, GraphicsUnit.Point, 0);
            label.ForeColor = Color.DimGray;
            label.Location = new Point(x, y);
            label.Name = label.Name;
            label.Size = new Size(100, 25);
            label.TabIndex = 0;
            label.Text = text;
        }

        private void ConfigureTextBox(TextBox textBox, int x, int y, int width)
        {
            textBox.BorderStyle = BorderStyle.FixedSingle;
            textBox.Font = new Font("Segoe UI", 9F, FontStyle.Regular, GraphicsUnit.Point, 0);
            textBox.ForeColor = Color.FromArgb(55, 55, 55);
            textBox.Location = new Point(x, y);
            textBox.Name = textBox.Name;
            textBox.Size = new Size(width, 31);
            textBox.TabIndex = 0;
        }

        private void ConfigureDivider(Panel panel, int x, int y, int width, int height)
        {
            panel.BackColor = Color.FromArgb(225, 232, 245);
            panel.Location = new Point(x, y);
            panel.Name = panel.Name;
            panel.Size = new Size(width, height);
            panel.TabIndex = 0;
        }

        private void ConfigureOptionRow(Label title, Label sub, CheckBox checkBox, string titleText, string subText, int x, int y)
        {
            ConfigureFieldLabel(title, titleText, x, y);
            title.Font = new Font("Segoe UI Semibold", 10F, FontStyle.Bold, GraphicsUnit.Point, 0);
            ConfigureHint(sub, subText, x, y + 28);
            checkBox.Appearance = Appearance.Button;
            checkBox.BackColor = Color.FromArgb(0, 82, 204);
            checkBox.Checked = true;
            checkBox.CheckState = CheckState.Checked;
            checkBox.FlatAppearance.BorderSize = 0;
            checkBox.FlatStyle = FlatStyle.Flat;
            checkBox.Font = new Font("Segoe UI", 8F, FontStyle.Bold, GraphicsUnit.Point, 0);
            checkBox.ForeColor = Color.White;
            checkBox.Location = new Point(585, y + 8);
            checkBox.Name = checkBox.Name;
            checkBox.Size = new Size(62, 32);
            checkBox.TabIndex = 0;
            checkBox.Text = "ON";
            checkBox.TextAlign = ContentAlignment.MiddleCenter;
            checkBox.UseVisualStyleBackColor = false;
        }

        private void ConfigurePrimaryButton(Button button, string text, int x, int y, int width)
        {
            button.BackColor = Color.FromArgb(0, 82, 204);
            button.FlatAppearance.BorderSize = 0;
            button.FlatStyle = FlatStyle.Flat;
            button.Font = new Font("Segoe UI", 9F, FontStyle.Bold, GraphicsUnit.Point, 0);
            button.ForeColor = Color.White;
            button.Location = new Point(x, y);
            button.Name = button.Name;
            button.Size = new Size(width, 36);
            button.TabIndex = 0;
            button.Text = text;
            button.UseVisualStyleBackColor = false;
        }

        private void ConfigureSecondaryButton(Button button, string text, int x, int y, int width)
        {
            button.BackColor = Color.White;
            button.FlatAppearance.BorderColor = Color.FromArgb(0, 82, 204);
            button.FlatStyle = FlatStyle.Flat;
            button.Font = new Font("Segoe UI", 9F, FontStyle.Bold, GraphicsUnit.Point, 0);
            button.ForeColor = Color.FromArgb(0, 82, 204);
            button.Location = new Point(x, y);
            button.Name = button.Name;
            button.Size = new Size(width, 36);
            button.TabIndex = 0;
            button.Text = text;
            button.UseVisualStyleBackColor = false;
        }

        private void ConfigureDangerButton(Button button, string text, int x, int y, int width)
        {
            ConfigureSecondaryButton(button, text, x, y, width);
            button.FlatAppearance.BorderColor = Color.IndianRed;
            button.ForeColor = Color.IndianRed;
        }

        private void ConfigureThemeCard(Panel panel, Color color, int x, int y)
        {
            panel.BackColor = color;
            panel.BorderStyle = BorderStyle.FixedSingle;
            panel.Location = new Point(x, y);
            panel.Name = panel.Name;
            panel.Size = new Size(172, 88);
            panel.TabIndex = 0;
        }

        private void ConfigureCardLabel(Label label, string text, int x, int y)
        {
            label.AutoSize = true;
            label.Font = new Font("Segoe UI Semibold", 9F, FontStyle.Bold, GraphicsUnit.Point, 0);
            label.ForeColor = Color.FromArgb(20, 52, 110);
            label.Location = new Point(x, y);
            label.Name = label.Name;
            label.Size = new Size(80, 25);
            label.TabIndex = 0;
            label.Text = text;
        }

        private void ConfigureColorSwatch(Panel panel, Color color, int x, int y)
        {
            panel.BackColor = color;
            panel.BorderStyle = BorderStyle.FixedSingle;
            panel.Location = new Point(x, y);
            panel.Name = panel.Name;
            panel.Size = new Size(46, 42);
            panel.TabIndex = 0;
        }

        private void ConfigureStatCard(Panel panel, Label title, Label value, string titleText, string valueText, int x, int y)
        {
            panel.BackColor = Color.FromArgb(244, 248, 255);
            panel.BorderStyle = BorderStyle.FixedSingle;
            panel.Controls.Add(value);
            panel.Controls.Add(title);
            panel.Location = new Point(x, y);
            panel.Name = panel.Name;
            panel.Size = new Size(300, 72);
            panel.TabIndex = 0;
            ConfigureFieldLabel(title, titleText, 16, 10);
            ConfigureHint(value, valueText, 16, 38);
            value.Font = new Font("Segoe UI", 10F, FontStyle.Bold, GraphicsUnit.Point, 0);
            value.ForeColor = Color.FromArgb(0, 82, 204);
        }

